import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

type Student = {
  id: string;
  name: string;
  email: string;
  department: string;
};

export default function StudentSection() {
  const [students, setStudents] = useState<Student[]>([]);

  useEffect(() => {
    const fetchStudents = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/students');
        const data = await response.json();
        setStudents(data);
      } catch (error) {
        console.error('Error fetching students:', error);
      }
    };
    fetchStudents();
  }, []);
  const [formData, setFormData] = useState<Omit<Student, 'id'>>({ 
    name: '', 
    email: '', 
    department: '' 
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('http://localhost:5000/api/students', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });
      const newStudent = await response.json();
      setStudents([...students, newStudent]);
      setFormData({ name: '', email: '', department: '' });
    } catch (error) {
      console.error('Error adding student:', error);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  return (
    <div className="container mt-5">
      <h1 className="mb-4 text-primary">Student Management</h1>
      <Link to="/" className="btn btn-secondary mb-4">Back to Home</Link>
      
      <form onSubmit={handleSubmit} className="mb-4">
        <div className="form-group mb-3">
          <input
            type="text"
            name="name"
            className="form-control"
            placeholder="Student Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group mb-3">
          <input
            type="email"
            name="email"
            className="form-control"
            placeholder="Email"
            value={formData.email}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group mb-3">
          <input
            type="text"
            name="department"
            className="form-control"
            placeholder="Department"
            value={formData.department}
            onChange={handleChange}
            required
          />
        </div>
        <button type="submit" className="btn btn-success">Add Student</button>
      </form>

      <Link to="/student-search" className="btn btn-primary mt-3">Search Students</Link>
    </div>
  );
}
